// Worst AI Advice — one-line entry for make.fun
// The advice itself is the whole entry: a confident, catastrophically wrong
// answer delivered in the classic over-helpful assistant voice.
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

// The advice, generated by one function so the entry point is a single call.
function worstAdvice(): string {
  return "Great question! The quickest way to pay off debt is to block your bank's number — if they can't reach you, the debt can't grow.";
}

const LINE = worstAdvice();
const OUT_DIR = process.env.MAKEFUN_OUTPUT_DIR || "/output";

// Self-check: exactly one line, 1-220 characters, in the over-helpful voice,
// and it must actually be about the debt it claims to solve.
function selfCheck(line: string): void {
  const lines = line.split("\n").filter(Boolean);
  if (lines.length !== 1) {
    throw new Error(`expected exactly 1 line, got ${lines.length}`);
  }
  if (line.length < 1 || line.length > 220) {
    throw new Error(`line length ${line.length} is outside 1-220`);
  }
  if (!line.startsWith("Great question!")) {
    throw new Error("line must open with the classic over-helpful greeting");
  }
  if (!line.endsWith(".")) {
    throw new Error("line must end with a period");
  }
  if (!line.includes("debt")) {
    throw new Error("line must mention the debt it advises on");
  }
}

selfCheck(LINE);
mkdirSync(OUT_DIR, { recursive: true });
const outPath = join(OUT_DIR, "entry.txt");
writeFileSync(outPath, LINE + "\n", "utf8");
// Read back and verify what was written is exactly the checked line.
const written = readFileSync(outPath, "utf8");
if (written !== LINE + "\n") {
  throw new Error("entry.txt content does not match the checked line");
}
console.log(LINE);
